const {test}=require('node:test');const assert=require('node:assert/strict');const ui=require('./inbox.js');
const row={id:'one',version:1,state:'pending',title:'Controls',problem:'Clarity',desired_outcome:'Labels',related_issue:'HLLV-007',created_at:'2026-10-08T00:00:00Z',updated_at:'2026-10-08T00:00:00Z',public_visible:false,history:[]};
test('responses are explicit and malformed/withdrawn records fail closed',()=>{const value={phase:'setup',checked_at:'2026-10-09T00:00:00Z',can_moderate:false,rows:[row]};assert.equal(ui.validate(value),value);for(const v of [null,{}, {...value,rows:[row,row]},{...value,rows:[{...row,state:'withdrawn'}]}])assert.throws(()=>ui.validate(v));});
test('filters search and ordering do not mutate records',()=>{const b={...row,id:'two',state:'declined',created_at:'2026-10-09T00:00:00Z'};const rows=[row,b];assert.equal(ui.matching(rows,'all','HLLV-007').length,2);assert.equal(ui.matching(rows,'closed')[0],b);assert.equal(ui.matching(rows,'all','','newest')[0],b);assert.equal(rows[0],row);});
test('UI cannot turn setup or published entries into writable decisions',()=>{assert.equal(ui.canEdit(row,{phase:'setup',can_moderate:true}),false);assert.equal(ui.canEdit(row,{phase:'review',can_moderate:true}),true);assert.equal(ui.canEdit({...row,state:'published'},{phase:'review',can_moderate:true}),false);});
test('text is escaped and bad dates are explicit',()=>{assert.equal(ui.esc('<a "x">'), '&lt;a &quot;x&quot;&gt;');assert.equal(ui.date('invalid'),'Not recorded');assert.equal(ui.date(null),'Not recorded');});
